import { useAuth } from "@/_core/hooks/useAuth";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { eventsByDayOfMonth } from "@shared/calendar";
import { filterActivities, filterGroups, filterMissionaries, filterPrayers } from "@shared/filtering";
import { CalendarDays, Check, ChevronLeft, ChevronRight, CircleDollarSign, ClipboardCheck, Edit3, FileDown, HeartHandshake, History, Mail, MapPin, Megaphone, Phone, Plus, Search, ShieldCheck, Sparkles, Sprout, UserCheck, UserX, UsersRound } from "lucide-react";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

export type ManagementView = "dashboard" | "missionaries" | "prayers" | "groups" | "activities" | "announcements" | "permissions" | "governance";

const viewCopy: Record<ManagementView, { eyebrow: string; title: string; description: string }> = {
  dashboard: { eyebrow: "TODAY AT A GLANCE", title: "平安，願您今天服事得力。", description: "從全局數據開始，留意每一個需要關懷、同行與代禱的訊號。" },
  missionaries: { eyebrow: "MISSIONARY DIRECTORY", title: "宣教士名冊", description: "集中管理外派同工檔案、支持承諾與前線聯絡資訊。" },
  prayers: { eyebrow: "PRAYER CARE", title: "代禱事項", description: "以清楚狀態追蹤每一個交託，並記錄每一次蒙應允的恩典。" },
  groups: { eyebrow: "SMALL GROUP CARE", title: "小組牧養", description: "將名冊、聚會、出席與關懷記錄放在同一個可持續跟進的脈絡中。" },
  activities: { eyebrow: "CHURCH CALENDAR", title: "活動行事曆", description: "建立清楚的教會活動節奏，並將活動指派給合適的小組。" },
  announcements: { eyebrow: "COMMUNICATION", title: "公告中心", description: "在對的時間，向對的群體傳遞清楚、溫暖且一致的訊息。" },
  permissions: { eyebrow: "ACCESS GOVERNANCE", title: "角色權限", description: "以 Admin、Leader、Member 三層權限，守護敏感牧養與支持資料。" },
  governance: { eyebrow: "DATA GOVERNANCE", title: "資料治理", description: "以受稽核的匯出、帳號生命週期與操作紀錄，守護教會資料的可用性與可追溯性。" },
};

const dateText = (value: Date | number | string | null | undefined) => value ? new Date(value).toLocaleDateString("zh-TW", { month: "long", day: "numeric", year: "numeric" }) : "—";
const datetimeText = (value: Date | number | string | null | undefined) => value ? new Date(value).toLocaleString("zh-TW", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" }) : "—";
const money = (value: number) => new Intl.NumberFormat("zh-TW", { style: "currency", currency: "TWD", maximumFractionDigits: 0 }).format(value);

export default function ManagementPage({ view }: { view: ManagementView }) {
  const { user } = useAuth();
  const copy = viewCopy[view];
  return <div className="mx-auto max-w-[1480px] animate-in fade-in duration-300">
    <header className="mb-7 flex flex-col gap-4 border-b border-[#e8e2d8] pb-7 sm:mb-8 sm:flex-row sm:items-end sm:justify-between">
      <div><p className="text-[10px] font-bold tracking-[0.2em] text-[#a06c3b]">{copy.eyebrow}</p><h1 className="mt-2 font-serif text-3xl font-semibold tracking-tight text-[#29483c] sm:text-[2.1rem]">{copy.title}</h1><p className="mt-2 max-w-2xl leading-7 text-[#758077]">{copy.description}</p></div>
      <div className="inline-flex w-fit items-center gap-2 rounded-full border border-[#e1d8ca] bg-[#fdfbf7] px-3 py-1.5 text-xs font-semibold text-[#6e6e63]"><span className="h-2 w-2 rounded-full bg-[#6f9b7e]" />目前身分：{user?.role}</div>
    </header>
    {view === "dashboard" && <DashboardPanel />}
    {view === "missionaries" && <MissionaryPanel />}
    {view === "prayers" && <PrayerPanel />}
    {view === "groups" && <GroupPanel />}
    {view === "activities" && <ActivityPanel />}
    {view === "announcements" && <AnnouncementPanel />}
    {view === "permissions" && <PermissionPanel />}
    {view === "governance" && <GovernancePanel />}
  </div>;
}

function EmptyState({ icon: Icon = Sparkles, title, detail }: { icon?: typeof Sparkles; title: string; detail: string }) {
  return <div className="grid min-h-52 place-items-center rounded-2xl border border-dashed border-[#dcd4c8] bg-[#fcfbf8] p-8 text-center"><div><div className="mx-auto mb-3 grid h-10 w-10 place-items-center rounded-xl bg-[#eef3ed] text-[#5f8b6c]"><Icon className="h-5 w-5" /></div><p className="font-semibold text-[#43544b]">{title}</p><p className="mt-1 max-w-sm text-sm leading-6 text-[#899289]">{detail}</p></div></div>;
}

function DashboardPanel() {
  const overview = trpc.dashboard.overview.useQuery(undefined, { retry: false });
  const data = overview.data;
  const cards = [
    { label: "啟用宣教士", value: data?.activeMissionaries ?? 0, note: "持續服事中的前線同工", icon: Sprout, tone: "bg-[#e9f1e8] text-[#477258]" },
    { label: "代禱中事項", value: data?.prayerCount ?? 0, note: "等候群體守望與更新", icon: HeartHandshake, tone: "bg-[#f8eee1] text-[#a06332]" },
    { label: "小組出席率", value: `${data?.attendanceRate ?? 0}%`, note: "已依所有出席紀錄計算", icon: ClipboardCheck, tone: "bg-[#e8eff3] text-[#4f7587]" },
    { label: "近期活動", value: data?.upcomingEvents.length ?? 0, note: "已發布、尚未開始的行程", icon: CalendarDays, tone: "bg-[#f2eaf2] text-[#835e82]" },
  ];
  return <div className="space-y-7"><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(card => <Card key={card.label} className="overflow-hidden border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardContent className="p-5"><div className="flex items-start justify-between"><div><p className="text-sm font-medium text-[#7e887f]">{card.label}</p><p className="mt-3 font-serif text-4xl font-semibold text-[#2d4438]">{overview.isLoading ? "—" : card.value}</p></div><div className={`grid h-10 w-10 place-items-center rounded-xl ${card.tone}`}><card.icon className="h-5 w-5" /></div></div><p className="mt-4 text-xs text-[#a0a79f]">{card.note}</p></CardContent></Card>)}</section>
    <section className="grid gap-5 lg:grid-cols-[1.25fr_0.75fr]"><Card className="border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardHeader className="flex-row items-center justify-between"><div><CardTitle className="font-serif text-xl text-[#334a3e]">接下來的活動</CardTitle><CardDescription className="mt-1">已發布且尚未開始的教會行程。</CardDescription></div><CalendarDays className="h-5 w-5 text-[#a06c3b]" /></CardHeader><CardContent>{data?.upcomingEvents.length ? <div className="divide-y divide-[#eee9e1]">{data.upcomingEvents.map(event => <div key={event.id} className="flex items-center gap-4 py-4 first:pt-0"><div className="w-12 rounded-xl bg-[#eff4ed] py-2 text-center text-[#456b53]"><p className="text-xs font-bold">{new Date(event.startsAt).toLocaleDateString("zh-TW", { month: "short" })}</p><p className="font-serif text-xl font-semibold">{new Date(event.startsAt).getDate()}</p></div><div className="min-w-0 flex-1"><p className="font-semibold text-[#44554b]">{event.title}</p><p className="mt-1 text-sm text-[#8d958e]">{datetimeText(event.startsAt)} · {event.location || "地點待定"}</p></div><ChevronRight className="h-4 w-4 text-[#b4bbb5]" /></div>)}</div> : <EmptyState icon={CalendarDays} title="尚無近期活動" detail="建立活動後，這裡會自動整理接下來值得預備的行程。" />}</CardContent></Card>
      <Card className="border-[#e8e2d8] bg-[#355f4d] text-white shadow-[0_20px_45px_rgba(40,75,60,0.16)]"><CardContent className="flex h-full min-h-64 flex-col p-7"><Sparkles className="h-6 w-6 text-[#e5bd7e]" /><p className="mt-8 font-serif text-2xl leading-snug">「各人不要單顧自己的事，也要顧別人的事。」</p><p className="mt-3 text-sm leading-6 text-white/70">本週可從代禱、缺席關懷與活動動員三個方向，留意尚待同行的人。</p><div className="mt-auto flex items-center gap-2 text-xs font-semibold tracking-wide text-[#e5bd7e]"><span className="h-px w-7 bg-[#e5bd7e]/70" />腓立比書 2:4</div></CardContent></Card></section></div>;
}

function MissionaryPanel() {
  const { user } = useAuth();
  const isAdmin = user?.role === "Admin";
  const missionaries = trpc.missionaries.list.useQuery();
  const supporters = trpc.missionaries.supporters.useQuery(undefined, { enabled: isAdmin });
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const commitments = trpc.missionaries.commitments.useQuery({ id: selectedId ?? 0 }, { enabled: isAdmin && !!selectedId });
  const create = trpc.missionaries.create.useMutation({ onSuccess: () => { missionaries.refetch(); toast.success("已建立宣教士檔案"); } });
  const update = trpc.missionaries.update.useMutation({ onSuccess: () => { missionaries.refetch(); toast.success("宣教士檔案已更新"); } });
  const toggle = trpc.missionaries.setStatus.useMutation({ onSuccess: () => missionaries.refetch() });
  const createSupporter = trpc.missionaries.createSupporter.useMutation({ onSuccess: () => { supporters.refetch(); toast.success("已新增支持者"); } });
  const createCommitment = trpc.missionaries.createCommitment.useMutation({ onSuccess: () => { commitments.refetch(); toast.success("支持承諾已登錄"); } });
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "inactive">("all");
  const allMissionaries = missionaries.data ?? [];
  const list = useMemo(() => filterMissionaries(allMissionaries, searchTerm, statusFilter), [allMissionaries, searchTerm, statusFilter]);
  const selected = list.find(item => item.id === selectedId) ?? null;
  const activeCommitments = commitments.data?.filter(item => item.status === "active") ?? [];
  const monthly = activeCommitments.reduce((sum, item) => { const n = Number(item.amount); return sum + n * (item.frequency === "monthly" ? 1 : item.frequency === "quarterly" ? 1 / 3 : item.frequency === "yearly" ? 1 / 12 : 0); }, 0);

  return <div className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><section><div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm text-[#778178]">顯示 {list.length}／{allMissionaries.length} 位同工</p><p className="mt-1 text-xs text-[#9a938a]">可依姓名、服事地區或差派機構快速查找。</p></div>{isAdmin && <MissionaryDialog title="新增宣教士" submit="建立檔案" onSubmit={input => create.mutate(input)} />}</div><div className="mb-5 grid gap-2 sm:grid-cols-[1fr_9rem]"><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#9aa39b]" /><Input value={searchTerm} onChange={event => setSearchTerm(event.target.value)} placeholder="搜尋姓名、地區或差派機構" className="border-[#e3ddd3] bg-[#fdfcf9] pl-9" /></div><Select value={statusFilter} onValueChange={value => setStatusFilter(value as "all" | "active" | "inactive")}><SelectTrigger className="border-[#e3ddd3] bg-[#fdfcf9]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">全部狀態</SelectItem><SelectItem value="active">啟用中</SelectItem><SelectItem value="inactive">已停用</SelectItem></SelectContent></Select></div>{missionaries.isLoading ? <EmptyState title="載入名冊中" detail="正在整理前線同工資料。" /> : list.length ? <div className="grid gap-4 sm:grid-cols-2">{list.map(missionary => <button key={missionary.id} onClick={() => setSelectedId(missionary.id)} className={`group rounded-2xl border p-5 text-left transition hover:-translate-y-0.5 hover:shadow-lg ${selectedId === missionary.id ? "border-[#7a9a7d] bg-[#f4f8f2] shadow-[0_12px_30px_rgba(57,93,76,0.09)]" : "border-[#e8e2d8] bg-[#fdfcf9]"}`}><div className="flex items-start gap-3"><div className="grid h-11 w-11 place-items-center overflow-hidden rounded-xl bg-[#e8f0ea] font-serif text-lg font-semibold text-[#477258]">{missionary.photoUrl ? <img src={missionary.photoUrl} alt="" className="h-full w-full object-cover" /> : missionary.name.slice(0, 1)}</div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><p className="truncate font-serif text-lg font-semibold text-[#395246]">{missionary.name}</p><StatusBadge status={missionary.status} /></div><p className="mt-1 truncate text-sm text-[#8a948b]">{missionary.sendingOrganization}</p></div></div><div className="mt-5 space-y-1.5 text-sm text-[#6f7c73]"><p className="flex items-center gap-2"><MapPin className="h-3.5 w-3.5 text-[#a06c3b]" />{missionary.ministryRegion}</p>{missionary.contactEmail && <p className="flex items-center gap-2 truncate"><Mail className="h-3.5 w-3.5 text-[#a06c3b]" />{missionary.contactEmail}</p>}</div></button>)}</div> : <EmptyState icon={Sprout} title={allMissionaries.length ? "沒有符合條件的宣教士" : "尚未建立宣教士資料"} detail={allMissionaries.length ? "請調整搜尋字詞或狀態篩選，以查看其他同工。" : "從新增宣教士開始，建立服事地區、差派機構與聯絡資訊。"} />}</section>
    <aside className="min-w-0">{selected ? <Card className="sticky top-6 border-[#e1d8ca] bg-[#fdfcf9] shadow-[0_18px_45px_rgba(57,75,62,0.08)]"><CardHeader><div className="flex items-start justify-between gap-3"><div><CardTitle className="font-serif text-2xl text-[#314a3d]">{selected.name}</CardTitle><CardDescription className="mt-1">{selected.ministryRegion} · {selected.sendingOrganization}</CardDescription></div><StatusBadge status={selected.status} /></div></CardHeader><CardContent className="space-y-6"><div className="grid grid-cols-2 gap-3 text-sm"><Info label="電子郵件" value={selected.contactEmail || "未填寫"} /><Info label="聯絡電話" value={selected.contactPhone || "未填寫"} /></div>{isAdmin && <div className="flex flex-wrap gap-2"><MissionaryDialog title="編輯宣教士" submit="儲存變更" initial={selected} onSubmit={input => update.mutate({ id: selected.id, ...input })} /><Button variant="outline" onClick={() => toggle.mutate({ id: selected.id, status: selected.status === "active" ? "inactive" : "active" })} className="rounded-xl border-[#dcd4c8]">{selected.status === "active" ? "停用檔案" : "重新啟用"}</Button></div>}{isAdmin && <div className="rounded-2xl bg-[#f5f1eb] p-4"><div className="flex items-start justify-between"><div><p className="text-xs font-bold tracking-wider text-[#9a7048]">支持總覽</p><p className="mt-1 font-serif text-3xl font-semibold text-[#405a49]">{money(monthly)}</p><p className="text-xs text-[#829087]">每月等值支持 · {activeCommitments.length} 筆進行中</p></div><CircleDollarSign className="h-6 w-6 text-[#a06c3b]" /></div></div>}{isAdmin && <SupportForms missionaryId={selected.id} supporters={supporters.data ?? []} onSupporter={input => createSupporter.mutate(input)} onCommitment={input => createCommitment.mutate(input)} />}{isAdmin && <div><p className="mb-2 text-sm font-semibold text-[#52645a]">支持承諾</p>{commitments.data?.length ? <div className="space-y-2">{commitments.data.map(item => <div key={item.id} className="flex items-center justify-between rounded-xl border border-[#ebe5db] px-3 py-2.5 text-sm"><div><p className="font-medium text-[#48594f]">{item.supporterName}</p><p className="mt-0.5 text-xs text-[#9a938a]">{frequencyLabel(item.frequency)} · {item.status === "active" ? "進行中" : "已暫停／結束"}</p></div><p className="font-serif text-lg font-semibold text-[#3e5d4a]">{money(Number(item.amount))}</p></div>)}</div> : <p className="text-sm text-[#919991]">尚無支持承諾資料。</p>}</div>}</CardContent></Card> : <EmptyState icon={Sprout} title="選擇一位宣教士" detail="點選左側名片，即可查看詳細資料與支持總覽。" />}</aside></div>;
}

function MissionaryDialog({ title, submit, initial, onSubmit }: { title: string; submit: string; initial?: any; onSubmit: (input: any) => void }) {
  const [open, setOpen] = useState(false);
  const [photoUrl, setPhotoUrl] = useState<string | null>(initial?.photoUrl ?? null);
  const uploadPhoto = trpc.missionaries.uploadPhoto.useMutation({ onSuccess: data => { setPhotoUrl(data.url); toast.success("照片已上傳"); }, onError: error => toast.error(error.message) });
  const send = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); onSubmit({ name: String(form.get("name")), ministryRegion: String(form.get("region")), sendingOrganization: String(form.get("organization")), contactEmail: String(form.get("email")) || null, contactPhone: String(form.get("phone")) || null, photoUrl, status: String(form.get("status")) as "active" | "inactive" }); setOpen(false); };
  const selectPhoto = (file?: File) => { if (!file) return; if (!["image/jpeg", "image/png", "image/webp"].includes(file.type)) { toast.error("請選擇 JPG、PNG 或 WEBP 圖片。"); return; } if (file.size > 3_000_000) { toast.error("照片大小請控制在 3MB 以內。"); return; } const reader = new FileReader(); reader.onload = () => { const base64 = String(reader.result).split(",")[1]; if (base64) uploadPhoto.mutate({ filename: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataBase64: base64 }); }; reader.readAsDataURL(file); };
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="rounded-xl bg-[#355f4d] hover:bg-[#294a3d]">{initial ? <><Edit3 className="mr-2 h-4 w-4" />編輯資料</> : <><Plus className="mr-2 h-4 w-4" />新增宣教士</>}</Button></DialogTrigger><DialogContent className="max-h-[92vh] overflow-y-auto rounded-2xl sm:max-w-xl"><DialogHeader><DialogTitle className="font-serif text-2xl text-[#314a3d]">{title}</DialogTitle><DialogDescription>請完整填寫聯絡與服事資料，以利牧養與支持團隊跟進。</DialogDescription></DialogHeader><form onSubmit={send} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="姓名" name="name" defaultValue={initial?.name} required /><Field label="服事地區" name="region" defaultValue={initial?.ministryRegion} required /><Field label="差派機構" name="organization" defaultValue={initial?.sendingOrganization} required /><Field label="聯絡電話" name="phone" defaultValue={initial?.contactPhone} /><Field label="電子郵件" name="email" type="email" defaultValue={initial?.contactEmail} /><div><Label htmlFor="photo">宣教士照片</Label><Input id="photo" type="file" accept="image/jpeg,image/png,image/webp" onChange={event => selectPhoto(event.target.files?.[0])} className="mt-2" /><p className="mt-1.5 text-xs text-[#958d84]">JPG、PNG 或 WEBP，檔案上限 3MB。</p>{uploadPhoto.isPending && <p className="mt-1 text-xs text-[#a06c3b]">照片上傳中…</p>}{photoUrl && <img src={photoUrl} alt="照片預覽" className="mt-2 h-14 w-14 rounded-xl object-cover" />}</div></div><div><Label>狀態</Label><Select name="status" defaultValue={initial?.status ?? "active"}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="active">啟用</SelectItem><SelectItem value="inactive">停用</SelectItem></SelectContent></Select></div><DialogFooter><Button type="submit" disabled={uploadPhoto.isPending} className="rounded-xl bg-[#355f4d] hover:bg-[#294a3d]">{submit}</Button></DialogFooter></form></DialogContent></Dialog>;
}

function SupportForms({ missionaryId, supporters, onSupporter, onCommitment }: { missionaryId: number; supporters: any[]; onSupporter: (input: any) => void; onCommitment: (input: any) => void }) {
  const [showSupporter, setShowSupporter] = useState(false); const [showCommitment, setShowCommitment] = useState(false);
  return <div className="flex flex-wrap gap-2"><Dialog open={showSupporter} onOpenChange={setShowSupporter}><DialogTrigger asChild><Button variant="outline" className="rounded-xl border-[#d8d0c3] text-[#526a58]"><Plus className="mr-1.5 h-4 w-4" />新增支持者</Button></DialogTrigger><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>新增支持者</DialogTitle></DialogHeader><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); onSupporter({ name: String(f.get("name")), email: String(f.get("email")) || null, phone: String(f.get("phone")) || null, notes: String(f.get("notes")) || null }); setShowSupporter(false); }} className="space-y-3"><Field label="姓名" name="name" required /><Field label="電子郵件" name="email" type="email" /><Field label="電話" name="phone" /><div><Label>備註</Label><Textarea name="notes" className="mt-2" /></div><DialogFooter><Button type="submit">儲存支持者</Button></DialogFooter></form></DialogContent></Dialog>
    <Dialog open={showCommitment} onOpenChange={setShowCommitment}><DialogTrigger asChild><Button variant="outline" className="rounded-xl border-[#d8d0c3] text-[#526a58]"><CircleDollarSign className="mr-1.5 h-4 w-4" />登錄支持</Button></DialogTrigger><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>新增支持承諾</DialogTitle></DialogHeader><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); onCommitment({ missionaryId, supporterId: Number(f.get("supporterId")), amount: Number(f.get("amount")), frequency: String(f.get("frequency")), currency: "TWD", status: "active" }); setShowCommitment(false); }} className="space-y-3"><div><Label>支持者</Label><Select name="supporterId" required><SelectTrigger className="mt-2"><SelectValue placeholder="選擇支持者" /></SelectTrigger><SelectContent>{supporters.map(person => <SelectItem key={person.id} value={String(person.id)}>{person.name}</SelectItem>)}</SelectContent></Select></div><Field label="支持金額（TWD）" name="amount" type="number" required /><div><Label>支持頻率</Label><Select name="frequency" defaultValue="monthly"><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="monthly">每月</SelectItem><SelectItem value="quarterly">每季</SelectItem><SelectItem value="yearly">每年</SelectItem><SelectItem value="one_time">一次性</SelectItem></SelectContent></Select></div><DialogFooter><Button type="submit" disabled={!supporters.length}>登錄承諾</Button></DialogFooter></form>{!supporters.length && <p className="text-xs text-[#a06c3b]">請先建立支持者資料。</p>}</DialogContent></Dialog></div>;
}

function PrayerPanel() {
  const { user } = useAuth(); const isAdmin = user?.role === "Admin";
  const missionaries = trpc.missionaries.list.useQuery(); const prayers = trpc.missionaries.prayers.useQuery({});
  const create = trpc.missionaries.createPrayer.useMutation({ onSuccess: () => { prayers.refetch(); toast.success("代禱事項已建立"); } });
  const update = trpc.missionaries.updatePrayer.useMutation({ onSuccess: () => prayers.refetch() });
  const [filter, setFilter] = useState<"current" | "answered" | "archived">("current");
  const allPrayers = prayers.data ?? [];
  const visiblePrayers = useMemo(() => filterPrayers(allPrayers, filter), [allPrayers, filter]);
  const filterCopy = filter === "current" ? "代禱中" : filter === "answered" ? "已回應" : "已歸檔";
  return <div className="space-y-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex w-full gap-2 overflow-x-auto pb-1 sm:w-auto"><Button size="sm" variant={filter === "current" ? "default" : "outline"} onClick={() => setFilter("current")} className={filter === "current" ? "rounded-full bg-[#355f4d] hover:bg-[#294a3d]" : "rounded-full"}>代禱中</Button><Button size="sm" variant={filter === "answered" ? "default" : "outline"} onClick={() => setFilter("answered")} className={filter === "answered" ? "rounded-full bg-[#355f4d] hover:bg-[#294a3d]" : "rounded-full"}>已回應</Button>{isAdmin && <Button size="sm" variant={filter === "archived" ? "default" : "outline"} onClick={() => setFilter("archived")} className={filter === "archived" ? "rounded-full bg-[#355f4d] hover:bg-[#294a3d]" : "rounded-full"}>已歸檔</Button>}</div>{isAdmin && <Dialog><DialogTrigger asChild><Button className="rounded-xl bg-[#355f4d] hover:bg-[#294a3d]"><Plus className="mr-2 h-4 w-4" />新增代禱事項</Button></DialogTrigger><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle className="font-serif text-2xl">建立代禱事項</DialogTitle></DialogHeader><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); create.mutate({ missionaryId: Number(f.get("missionaryId")), title: String(f.get("title")), content: String(f.get("content")), status: "praying" }); }} className="space-y-4"><div><Label>所屬宣教士</Label><Select name="missionaryId" required><SelectTrigger className="mt-2"><SelectValue placeholder="選擇宣教士" /></SelectTrigger><SelectContent>{(missionaries.data ?? []).map(m => <SelectItem key={m.id} value={String(m.id)}>{m.name}</SelectItem>)}</SelectContent></Select></div><Field label="代禱主題" name="title" required /><div><Label>內容</Label><Textarea name="content" required className="mt-2 min-h-28" /></div><DialogFooter><Button type="submit">建立事項</Button></DialogFooter></form></DialogContent></Dialog>}</div><p className="text-sm text-[#7d887f]">目前顯示 <span className="font-semibold text-[#486050]">{visiblePrayers.length}</span> 項「{filterCopy}」事項。</p>{visiblePrayers.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{visiblePrayers.map(item => <Card key={item.id} className="border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardHeader className="pb-3"><div className="flex items-start justify-between gap-3"><div><CardTitle className="font-serif text-xl text-[#405a49]">{item.title}</CardTitle><CardDescription className="mt-1">{item.missionaryName} · {dateText(item.createdAt)}</CardDescription></div><PrayerBadge status={item.status} /></div></CardHeader><CardContent><p className="line-clamp-4 text-sm leading-6 text-[#67746b]">{item.content}</p>{isAdmin && <div className="mt-5 flex flex-wrap gap-2">{!item.isArchived && <Button size="sm" variant="outline" className="rounded-lg" onClick={() => update.mutate({ id: item.id, title: item.title, content: item.content, status: item.status === "praying" ? "answered" : "praying", isArchived: false })}>{item.status === "praying" ? "標示已回應" : "改為代禱中"}</Button>}<Button size="sm" variant="ghost" className="rounded-lg text-[#8b8072]" onClick={() => update.mutate({ id: item.id, title: item.title, content: item.content, status: item.status, isArchived: !item.isArchived })}>{item.isArchived ? "恢復顯示" : "歸檔"}</Button></div>}</CardContent></Card>)}</div> : <EmptyState icon={HeartHandshake} title={`尚無「${filterCopy}」事項`} detail={filter === "current" ? "建立代禱事項後，將可用「代禱中」與「已回應」清楚追蹤。" : "您可切換篩選條件，查看其他代禱記錄。"} />}</div>;
}

function GroupPanel() {
  const { user } = useAuth(); const isAdmin = user?.role === "Admin";
  const groupsQuery = trpc.groups.list.useQuery(undefined, { retry: false }); const users = trpc.users.list.useQuery(undefined, { enabled: isAdmin });
  const [groupId, setGroupId] = useState<number | null>(null); const [groupSearch, setGroupSearch] = useState(""); const groups = groupsQuery.data ?? []; const filteredGroups = useMemo(() => filterGroups(groups, groupSearch), [groups, groupSearch]); const selected = groups.find(g => g.id === groupId) ?? null;
  useEffect(() => { if (!groupId && groups.length) setGroupId(groups[0].id); }, [groupId, groups]);
  const members = trpc.groups.members.useQuery({ groupId: groupId ?? 0 }, { enabled: !!groupId }); const meetings = trpc.groups.meetings.useQuery({ groupId: groupId ?? 0 }, { enabled: !!groupId }); const careLogs = trpc.groups.careLogs.useQuery({ groupId: groupId ?? 0 }, { enabled: !!groupId }); const attendanceSummary = trpc.groups.attendanceSummary.useQuery({ groupId: groupId ?? 0 }, { enabled: !!groupId });
  const [meetingId, setMeetingId] = useState<number | null>(null); const attendance = trpc.groups.attendance.useQuery({ meetingId: meetingId ?? 0 }, { enabled: !!meetingId });
  const createGroup = trpc.groups.create.useMutation({ onSuccess: () => { groupsQuery.refetch(); toast.success("小組已建立"); } }); const updateGroup = trpc.groups.update.useMutation({ onSuccess: () => groupsQuery.refetch() }); const addMember = trpc.groups.addMember.useMutation({ onSuccess: () => members.refetch() }); const createMeeting = trpc.groups.createMeeting.useMutation({ onSuccess: () => meetings.refetch() }); const attendanceMutation = trpc.groups.setAttendance.useMutation({ onSuccess: () => attendance.refetch() }); const createCare = trpc.groups.createCareLog.useMutation({ onSuccess: () => careLogs.refetch() });
  const attendanceMap = new Map((attendance.data ?? []).map(row => [row.groupMemberId, row.status]));
  return <div className="grid gap-6 xl:grid-cols-[300px_1fr]"><Card className="h-fit border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardHeader className="flex-row items-center justify-between"><CardTitle className="font-serif text-xl text-[#405a49]">我的小組</CardTitle>{isAdmin && <GroupDialog users={users.data ?? []} onSubmit={input => createGroup.mutate(input)} />}</CardHeader><CardContent>{groups.length ? <><div className="relative mb-3"><Search className="pointer-events-none absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-[#9aa39b]" /><Input value={groupSearch} onChange={event => setGroupSearch(event.target.value)} placeholder="搜尋小組、牧區或帶領人" className="h-9 border-[#e6dfd6] bg-[#fbfaf7] pl-8 text-xs" /></div>{filteredGroups.length ? <div className="space-y-2">{filteredGroups.map(group => <button key={group.id} onClick={() => { setGroupId(group.id); setMeetingId(null); }} className={`w-full rounded-xl p-3 text-left transition ${group.id === groupId ? "bg-[#e9f1e8]" : "hover:bg-[#f5f1eb]"}`}><p className="font-semibold text-[#46594e]">{group.name}</p><p className="mt-1 text-xs text-[#8d958e]">{group.district} · {group.leaderName || "未指派帶領人"}</p></button>)}</div> : <p className="rounded-xl bg-[#f7f4ee] px-3 py-4 text-center text-xs leading-5 text-[#8d958e]">找不到符合條件的小組。</p>}</> : <EmptyState icon={UsersRound} title="尚無小組" detail="Admin 可先建立小組與指派帶領人。" />}</CardContent></Card>
    {selected ? <div className="space-y-5"><Card className="border-[#e1d8ca] bg-[#fdfcf9] shadow-none"><CardContent className="flex flex-col gap-4 p-6 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex items-center gap-2"><h2 className="font-serif text-2xl font-semibold text-[#405a49]">{selected.name}</h2><StatusBadge status={selected.status} /></div><p className="mt-2 text-sm text-[#78847b]">{selected.district} · 帶領人：{selected.leaderName || "未指派"}</p>{selected.description && <p className="mt-3 max-w-2xl text-sm leading-6 text-[#69766d]">{selected.description}</p>}</div><GroupDialog users={users.data ?? []} initial={selected} onSubmit={input => updateGroup.mutate({ id: selected.id, ...input })} /></CardContent></Card><div className="grid gap-3 sm:grid-cols-3"><Info label="已記錄聚會" value={`${attendanceSummary.data?.meetingCount ?? 0} 次`} /><Info label="有效點名紀錄" value={`${attendanceSummary.data?.totalRecords ?? 0} 筆`} /><Info label="小組出席率" value={`${attendanceSummary.data?.rate ?? 0}%`} /></div>
      <div className="grid gap-5 lg:grid-cols-2"><Card className="border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardHeader className="flex-row items-center justify-between"><div><CardTitle className="font-serif text-xl text-[#405a49]">成員名冊</CardTitle><CardDescription>{members.data?.length ?? 0} 位成員</CardDescription></div><Dialog><DialogTrigger asChild><Button size="sm" variant="outline" className="rounded-lg"><Plus className="mr-1 h-3.5 w-3.5" />新增成員</Button></DialogTrigger><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>新增小組成員</DialogTitle></DialogHeader><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); addMember.mutate({ groupId: selected.id, name: String(f.get("name")), email: String(f.get("email")) || null, phone: String(f.get("phone")) || null }); }} className="space-y-3"><Field label="姓名" name="name" required /><Field label="電子郵件" name="email" type="email" /><Field label="電話" name="phone" /><DialogFooter><Button type="submit">加入小組</Button></DialogFooter></form></DialogContent></Dialog></CardHeader><CardContent>{members.data?.length ? <div className="divide-y divide-[#eee9e1]">{members.data.map(member => <div key={member.id} className="flex items-center justify-between py-3 first:pt-0"><div><p className="font-medium text-[#52645a]">{member.name}</p><p className="mt-0.5 text-xs text-[#9a938a]">{member.phone || member.email || "聯絡資訊待補"}</p></div><span className="text-xs text-[#a06c3b]">{dateText(member.joinedAt)} 加入</span></div>)}</div> : <EmptyState icon={UsersRound} title="名冊尚未加入成員" detail="新增成員後可開始點名與記錄關懷。" />}</CardContent></Card>
        <Card className="border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardHeader className="flex-row items-center justify-between"><div><CardTitle className="font-serif text-xl text-[#405a49]">聚會與出席</CardTitle><CardDescription>逐次點名，累積健康的參與脈絡。</CardDescription></div><Dialog><DialogTrigger asChild><Button size="sm" variant="outline" className="rounded-lg"><Plus className="mr-1 h-3.5 w-3.5" />建立聚會</Button></DialogTrigger><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>建立小組聚會</DialogTitle></DialogHeader><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); createMeeting.mutate({ groupId: selected.id, title: String(f.get("title")), heldAt: new Date(String(f.get("heldAt"))).getTime(), notes: String(f.get("notes")) || null }); }} className="space-y-3"><Field label="聚會主題" name="title" required /><div><Label>聚會時間</Label><Input name="heldAt" type="datetime-local" required className="mt-2" /></div><div><Label>備註</Label><Textarea name="notes" className="mt-2" /></div><DialogFooter><Button type="submit">建立並開始點名</Button></DialogFooter></form></DialogContent></Dialog></CardHeader><CardContent><div className="space-y-2">{meetings.data?.length ? meetings.data.map(meeting => <button key={meeting.id} onClick={() => setMeetingId(meeting.id)} className={`flex w-full items-center justify-between rounded-xl px-3 py-2.5 text-left ${meetingId === meeting.id ? "bg-[#eef4ec]" : "hover:bg-[#f5f1eb]"}`}><div><p className="font-medium text-[#52645a]">{meeting.title}</p><p className="mt-0.5 text-xs text-[#949c95]">{datetimeText(meeting.heldAt)}</p></div><ChevronRight className="h-4 w-4 text-[#a6aea7]" /></button>) : <p className="text-sm text-[#929a92]">尚無聚會記錄。</p>}</div></CardContent></Card></div>
      {meetingId && <Card className="border-[#d7e4d5] bg-[#fbfdf9] shadow-none"><CardHeader><CardTitle className="font-serif text-xl text-[#405a49]">出席點名</CardTitle><CardDescription>點選成員即可在「出席」與「缺席」之間切換；可按需要標示請假。</CardDescription></CardHeader><CardContent>{members.data?.length ? <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{members.data.map(member => { const state = attendanceMap.get(member.id) ?? "absent"; return <div key={member.id} className="flex items-center justify-between rounded-xl border border-[#e4ebe1] bg-white px-3 py-2.5"><p className="font-medium text-[#52645a]">{member.name}</p><Select value={state} onValueChange={status => attendanceMutation.mutate({ meetingId, memberId: member.id, status: status as "attended" | "absent" | "excused" })}><SelectTrigger className="h-8 w-24 border-0 bg-[#f4f1eb] text-xs"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="attended">出席</SelectItem><SelectItem value="absent">缺席</SelectItem><SelectItem value="excused">請假</SelectItem></SelectContent></Select></div>; })}</div> : <EmptyState icon={ClipboardCheck} title="請先建立成員名冊" detail="加入成員後即可記錄本次聚會出席。" />}</CardContent></Card>}
      <Card className="border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardHeader className="flex-row items-center justify-between"><div><CardTitle className="font-serif text-xl text-[#405a49]">關懷日誌</CardTitle><CardDescription>記錄跟進內容，讓關懷不會遺漏。</CardDescription></div><Dialog><DialogTrigger asChild><Button size="sm" variant="outline" className="rounded-lg"><Plus className="mr-1 h-3.5 w-3.5" />新增關懷</Button></DialogTrigger><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>建立關懷記錄</DialogTitle></DialogHeader><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); createCare.mutate({ groupMemberId: Number(f.get("memberId")), careDate: new Date(String(f.get("careDate"))).getTime(), method: String(f.get("method")) as any, summary: String(f.get("summary")), followUpStatus: String(f.get("follow")) as any }); }} className="space-y-3"><div><Label>關懷對象</Label><Select name="memberId" required><SelectTrigger className="mt-2"><SelectValue placeholder="選擇成員" /></SelectTrigger><SelectContent>{(members.data ?? []).map(m => <SelectItem key={m.id} value={String(m.id)}>{m.name}</SelectItem>)}</SelectContent></Select></div><div className="grid grid-cols-2 gap-3"><div><Label>日期</Label><Input name="careDate" type="date" required className="mt-2" /></div><div><Label>關懷方式</Label><Select name="method" defaultValue="phone"><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="phone">電話</SelectItem><SelectItem value="visit">探訪</SelectItem><SelectItem value="message">訊息</SelectItem><SelectItem value="meeting">面談</SelectItem><SelectItem value="other">其他</SelectItem></SelectContent></Select></div></div><div><Label>內容摘要</Label><Textarea name="summary" required className="mt-2" /></div><div><Label>跟進狀態</Label><Select name="follow" defaultValue="none"><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">暫無</SelectItem><SelectItem value="pending">待跟進</SelectItem><SelectItem value="completed">已完成</SelectItem></SelectContent></Select></div><DialogFooter><Button type="submit">儲存記錄</Button></DialogFooter></form></DialogContent></Dialog></CardHeader><CardContent>{careLogs.data?.length ? <div className="divide-y divide-[#eee9e1]">{careLogs.data.map(log => <div key={log.id} className="py-4 first:pt-0"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-medium text-[#52645a]">{log.memberName}</p><div className="flex gap-2"><Badge variant="outline" className="border-[#e3d7c9] bg-[#f9f3ea] text-[#956d45]">{careMethodLabel(log.method)}</Badge><Badge variant="outline" className="border-[#d4e2d1] bg-[#eff5ed] text-[#50755a]">{followLabel(log.followUpStatus)}</Badge></div></div><p className="mt-2 text-sm leading-6 text-[#717c74]">{log.summary}</p><p className="mt-2 text-xs text-[#a0a69f]">{dateText(log.careDate)}</p></div>)}</div> : <EmptyState icon={HeartHandshake} title="尚無關懷日誌" detail="關懷之後立即記錄，讓後續跟進更完整。" />}</CardContent></Card></div> : <EmptyState icon={UsersRound} title="選擇或建立小組" detail="您可從左側選取受指派的小組開始牧養工作。" />}</div>;
}

function GroupDialog({ users, initial, onSubmit }: { users: any[]; initial?: any; onSubmit: (input: any) => void }) {
  const { user } = useAuth(); const isAdmin = user?.role === "Admin"; const [open, setOpen] = useState(false); if (!isAdmin && !initial) return null;
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button size={initial ? "sm" : "default"} variant={initial ? "outline" : "default"} className={initial ? "rounded-lg" : "rounded-xl bg-[#355f4d] hover:bg-[#294a3d]"}>{initial ? "編輯小組" : <><Plus className="mr-2 h-4 w-4" />建立小組</>}</Button></DialogTrigger><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>{initial ? "編輯小組資料" : "建立小組"}</DialogTitle></DialogHeader><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); const input: Record<string, unknown> = { name: String(f.get("name")), district: String(f.get("district")), description: String(f.get("description")) || null }; if (isAdmin) { input.leaderUserId = String(f.get("leader")) === "unassigned" ? null : Number(f.get("leader")); input.status = String(f.get("status")); } onSubmit(input); setOpen(false); }} className="space-y-3"><Field label="小組名稱" name="name" defaultValue={initial?.name} required /><Field label="牧區" name="district" defaultValue={initial?.district} required />{isAdmin && <div><Label>帶領人</Label><Select name="leader" defaultValue={initial?.leaderUserId ? String(initial.leaderUserId) : "unassigned"}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="unassigned">尚未指派</SelectItem>{users.filter(u => u.role === "Leader" || u.role === "Admin").map(u => <SelectItem key={u.id} value={String(u.id)}>{u.name || u.email || `使用者 #${u.id}`}</SelectItem>)}</SelectContent></Select></div>}<div><Label>小組說明</Label><Textarea name="description" defaultValue={initial?.description ?? ""} className="mt-2" /></div>{isAdmin && <div><Label>狀態</Label><Select name="status" defaultValue={initial?.status ?? "active"}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="active">啟用</SelectItem><SelectItem value="inactive">停用</SelectItem></SelectContent></Select></div>}<DialogFooter><Button type="submit">儲存小組</Button></DialogFooter></form></DialogContent></Dialog>;
}

function ActivityPanel() {
  const { user } = useAuth(); const isAdmin = user?.role === "Admin"; const events = trpc.activities.events.useQuery(); const groups = trpc.groups.list.useQuery(undefined, { enabled: isAdmin }); const registrationSummaries = trpc.activities.registrationSummary.useQuery(undefined, { enabled: isAdmin }); const create = trpc.activities.createEvent.useMutation({ onSuccess: () => { events.refetch(); toast.success("活動已建立"); } });
  const [activitySearch, setActivitySearch] = useState(""); const filteredEvents = useMemo(() => filterActivities(events.data ?? [], activitySearch), [events.data, activitySearch]); const summaryByEvent = useMemo(() => new Map((registrationSummaries.data ?? []).map(summary => [summary.eventId, summary])), [registrationSummaries.data]);
  return <div className="space-y-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="relative w-full sm:max-w-sm"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#9aa39b]" /><Input value={activitySearch} onChange={event => setActivitySearch(event.target.value)} placeholder="搜尋活動名稱、地點或說明" className="border-[#e3ddd3] bg-[#fdfcf9] pl-9" /></div>{isAdmin && <ActivityDialog groups={groups.data ?? []} onSubmit={input => create.mutate(input)} />}</div><p className="text-sm text-[#7d887f]">目前顯示 <span className="font-semibold text-[#486050]">{filteredEvents.length}</span> 項活動。</p><ActivityCalendar events={filteredEvents} />{isAdmin && <ActivityRegistrationSummary events={filteredEvents} summaries={summaryByEvent} />}{filteredEvents.length ? <div><div className="mb-3 flex items-center gap-2"><span className="h-px flex-1 bg-[#e5dfd5]" /><p className="text-xs font-bold tracking-[0.14em] text-[#a29483]">活動列表</p><span className="h-px flex-1 bg-[#e5dfd5]" /></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filteredEvents.map(event => <Card key={event.id} className="overflow-hidden border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><div className="h-1.5 bg-[#89a975]" /><CardContent className="p-5"><div className="flex gap-4"><div className="w-12 rounded-xl bg-[#edf4eb] py-2 text-center text-[#477258]"><p className="text-[10px] font-bold">{new Date(event.startsAt).toLocaleDateString("zh-TW", { month: "short" })}</p><p className="font-serif text-xl font-semibold">{new Date(event.startsAt).getDate()}</p></div><div className="min-w-0"><h3 className="font-serif text-xl font-semibold text-[#405a49]">{event.title}</h3><p className="mt-1 text-xs text-[#929a92]">{datetimeText(event.startsAt)}</p></div></div><p className="mt-5 line-clamp-3 text-sm leading-6 text-[#6f7a72]">{event.description || "尚未提供活動說明。"}</p><p className="mt-4 flex items-center gap-1.5 text-xs text-[#9a7048]"><MapPin className="h-3.5 w-3.5" />{event.location || "地點待定"}</p></CardContent></Card>)}</div></div> : <EmptyState icon={CalendarDays} title={events.data?.length ? "沒有符合條件的活動" : "尚無活動"} detail={events.data?.length ? "請調整搜尋字詞，以查看其他已發布活動。" : "建立活動、設定時間與指定對象小組後，將在月曆與活動列表中呈現。"} />}</div>;
}

function ActivityRegistrationSummary({ events, summaries }: { events: any[]; summaries: Map<number, { registered: number; waitlisted: number; cancelled: number }> }) {
  if (!events.length) return null;
  return <Card className="border-[#dbe6d8] bg-[#f8fbf7] shadow-none"><CardHeader className="pb-3"><CardTitle className="font-serif text-xl text-[#405a49]">RSVP 報名摘要</CardTitle><CardDescription>活動容量、已報名與候補人數僅供 Admin 檢視。</CardDescription></CardHeader><CardContent className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{events.map(event => { const summary = summaries.get(event.id); return <div key={event.id} className="rounded-xl border border-[#e3ebe0] bg-white p-3"><p className="truncate font-medium text-[#516259]">{event.title}</p><p className="mt-1 text-xs text-[#879088]">容量：{event.capacity ?? "不限"}</p><div className="mt-2 flex gap-1.5"><Badge variant="outline" className="border-[#d1e3cf] bg-[#eff6ed] text-[#50775a]">已報名 {summary?.registered ?? 0}</Badge>{(summary?.waitlisted ?? 0) > 0 && <Badge variant="outline" className="border-[#ead9b9] bg-[#fcf6e8] text-[#9b6f32]">候補 {summary?.waitlisted}</Badge>}</div></div>; })}</CardContent></Card>;
}

function ActivityCalendar({ events }: { events: any[] }) {
  const [month, setMonth] = useState(() => new Date(new Date().getFullYear(), new Date().getMonth(), 1));
  const firstDay = new Date(month.getFullYear(), month.getMonth(), 1); const totalDays = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate(); const leading = firstDay.getDay();
  const cells = Array.from({ length: leading + totalDays }, (_, index) => index < leading ? null : index - leading + 1);
  const eventsByDay = eventsByDayOfMonth(events, month);
  return <Card className="overflow-hidden border-[#e3dbcf] bg-[#fdfcf9] shadow-none"><CardHeader className="flex-row items-center justify-between border-b border-[#eee9e1] pb-4"><div><CardTitle className="font-serif text-2xl text-[#405a49]">活動行事曆</CardTitle><CardDescription className="mt-1">依日期整理已發布的教會行程。</CardDescription></div><div className="flex items-center gap-1"><Button variant="ghost" size="icon" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))} aria-label="上一個月"><ChevronLeft className="h-4 w-4" /></Button><p className="min-w-28 text-center font-serif text-lg font-semibold text-[#52645a]">{month.toLocaleDateString("zh-TW", { year: "numeric", month: "long" })}</p><Button variant="ghost" size="icon" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))} aria-label="下一個月"><ChevronRight className="h-4 w-4" /></Button></div></CardHeader><CardContent className="p-0"><div className="grid grid-cols-7 border-b border-[#eee9e1] bg-[#f8f5ef]">{["日", "一", "二", "三", "四", "五", "六"].map(day => <p key={day} className="py-2 text-center text-xs font-bold text-[#989187]">{day}</p>)}</div><div className="grid grid-cols-7">{cells.map((day, index) => <div key={`${day}-${index}`} className="min-h-24 border-b border-r border-[#eee9e1] p-2 last:border-r-0 sm:min-h-30">{day && <><p className={`grid h-6 w-6 place-items-center rounded-full text-xs font-semibold ${day === new Date().getDate() && month.getMonth() === new Date().getMonth() && month.getFullYear() === new Date().getFullYear() ? "bg-[#355f4d] text-white" : "text-[#69766d]"}`}>{day}</p><div className="mt-1 space-y-1">{(eventsByDay.get(day) ?? []).slice(0, 2).map(event => <div key={event.id} title={event.title} className="truncate rounded-md bg-[#e7f0e4] px-1.5 py-1 text-[10px] font-medium text-[#416a4e]">{new Date(event.startsAt).toLocaleTimeString("zh-TW", { hour: "2-digit", minute: "2-digit" })} {event.title}</div>)}{(eventsByDay.get(day) ?? []).length > 2 && <p className="text-[10px] text-[#a06c3b]">另有 {(eventsByDay.get(day) ?? []).length - 2} 項</p>}</div></>}</div>)}</div></CardContent></Card>;
}

function ActivityDialog({ groups, onSubmit }: { groups: any[]; onSubmit: (input: any) => void }) {
  return <Dialog><DialogTrigger asChild><Button className="rounded-xl bg-[#355f4d] hover:bg-[#294a3d]"><Plus className="mr-2 h-4 w-4" />新增活動</Button></DialogTrigger><DialogContent className="max-h-[92vh] overflow-y-auto rounded-2xl"><DialogHeader><DialogTitle>建立教會活動</DialogTitle></DialogHeader><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); const capacity = String(f.get("capacity") || ""); onSubmit({ title: String(f.get("title")), description: String(f.get("description")) || null, location: String(f.get("location")) || null, capacity: capacity ? Number(capacity) : null, startsAt: new Date(String(f.get("startsAt"))).getTime(), endsAt: String(f.get("endsAt")) ? new Date(String(f.get("endsAt"))).getTime() : null, isPublished: true, groupIds: f.getAll("groupIds").map(Number) }); }} className="space-y-3"><Field label="活動名稱" name="title" required /><div className="grid gap-3 sm:grid-cols-2"><div><Label>開始時間</Label><Input name="startsAt" type="datetime-local" required className="mt-2" /></div><div><Label>結束時間（選填）</Label><Input name="endsAt" type="datetime-local" className="mt-2" /></div></div><div><Label>人數上限（選填）</Label><Input name="capacity" type="number" min="1" className="mt-2" placeholder="留空代表不限人數" /><p className="mt-1 text-xs text-[#9a938a]">設定上限後，額滿的新報名將列為候補。</p></div><Field label="活動地點" name="location" /><div><Label>活動說明</Label><Textarea name="description" className="mt-2" /></div><GroupChecks groups={groups} /><DialogFooter><Button type="submit">發布活動</Button></DialogFooter></form></DialogContent></Dialog>;
}

function AnnouncementPanel() {
  const { user } = useAuth(); const isAdmin = user?.role === "Admin"; const announcements = trpc.activities.announcements.useQuery(); const groups = trpc.groups.list.useQuery(undefined, { enabled: isAdmin }); const create = trpc.activities.createAnnouncement.useMutation({ onSuccess: () => { announcements.refetch(); toast.success("公告已發布"); } });
  return <div><div className="mb-5 flex justify-end">{isAdmin && <Dialog><DialogTrigger asChild><Button className="rounded-xl bg-[#355f4d] hover:bg-[#294a3d]"><Plus className="mr-2 h-4 w-4" />發布公告</Button></DialogTrigger><DialogContent className="max-h-[92vh] overflow-y-auto rounded-2xl"><DialogHeader><DialogTitle>建立公告</DialogTitle></DialogHeader><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); create.mutate({ title: String(f.get("title")), content: String(f.get("content")), isPublished: true, groupIds: f.getAll("groupIds").map(Number) }); }} className="space-y-3"><Field label="公告標題" name="title" required /><div><Label>公告內容</Label><Textarea name="content" required className="mt-2 min-h-36" /></div><GroupChecks groups={groups.data ?? []} /><DialogFooter><Button type="submit">發布公告</Button></DialogFooter></form></DialogContent></Dialog>}</div>{announcements.data?.length ? <div className="space-y-4">{announcements.data.map(item => <Card key={item.id} className="border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardContent className="p-6"><div className="flex items-start justify-between gap-3"><div><p className="text-[10px] font-bold tracking-[0.16em] text-[#a06c3b]">CHURCH NOTICE</p><h2 className="mt-2 font-serif text-2xl font-semibold text-[#405a49]">{item.title}</h2></div><Badge variant="outline" className="border-[#d4e2d1] bg-[#eff5ed] text-[#50755a]">已發布</Badge></div><p className="mt-4 whitespace-pre-wrap text-sm leading-7 text-[#66736b]">{item.content}</p><p className="mt-5 text-xs text-[#a0a79f]">發布於 {datetimeText(item.publishedAt || item.createdAt)}</p></CardContent></Card>)}</div> : <EmptyState icon={Megaphone} title="尚無公告" detail="發布公告後，所有具檢視權限的會友都可在此閱讀。" />}</div>;
}

function GovernancePanel() {
  const { user } = useAuth(); const isAdmin = user?.role === "Admin";
  const users = trpc.users.list.useQuery(undefined, { enabled: isAdmin }); const auditLogs = trpc.governance.auditLogs.useQuery({ limit: 30 }, { enabled: isAdmin });
  const exportCsv = trpc.governance.exportCsv.useMutation({ onSuccess: data => { const url = URL.createObjectURL(new Blob([data.csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = data.filename; link.click(); URL.revokeObjectURL(url); auditLogs.refetch(); toast.success(`已準備 ${data.rowCount} 筆資料的匯出檔。`); }, onError: error => toast.error(error.message) });
  const setStatus = trpc.users.setStatus.useMutation({ onSuccess: () => { users.refetch(); auditLogs.refetch(); toast.success("帳號狀態已更新"); }, onError: error => toast.error(error.message) });
  if (!isAdmin) return <EmptyState icon={ShieldCheck} title="您沒有資料治理的存取權" detail="資料匯出、稽核紀錄與帳號生命週期僅限 Admin 使用。" />;
  const resources = [{ key: "missionaries", label: "宣教士名冊" }, { key: "supportCommitments", label: "支持承諾" }, { key: "prayers", label: "代禱事項" }, { key: "groups", label: "小組資料" }, { key: "groupMembers", label: "小組成員" }, { key: "attendance", label: "出席紀錄" }, { key: "careLogs", label: "關懷日誌" }, { key: "events", label: "活動" }, { key: "announcements", label: "公告" }] as const;
  const requestExport = (resource: typeof resources[number]["key"], label: string) => { if (window.confirm(`即將下載「${label}」CSV。檔案可能含有個人或敏感牧養資料，請確認儲存位置安全。`)) exportCsv.mutate({ resource }); };
  return <div className="space-y-6"><Card className="border-[#e3dbcf] bg-[#fdfcf9] shadow-none"><CardHeader><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#edf4eb] text-[#477258]"><FileDown className="h-5 w-5" /></div><div><CardTitle className="font-serif text-xl text-[#405a49]">受稽核資料匯出</CardTitle><CardDescription className="mt-1">每次匯出均會記錄在操作稽核中。請僅下載至受管理、受加密的儲存位置。</CardDescription></div></div></CardHeader><CardContent className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{resources.map(resource => <Button key={resource.key} variant="outline" disabled={exportCsv.isPending} onClick={() => requestExport(resource.key, resource.label)} className="justify-start rounded-xl border-[#e3ddd3] text-[#4f6257]"><FileDown className="mr-2 h-4 w-4 text-[#a06c3b]" />匯出{resource.label}</Button>)}</CardContent></Card>
    <div className="grid gap-6 xl:grid-cols-[1.05fr_0.95fr]"><Card className="border-[#e3dbcf] bg-[#fdfcf9] shadow-none"><CardHeader><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#f8eee1] text-[#a06332]"><UserCheck className="h-5 w-5" /></div><div><CardTitle className="font-serif text-xl text-[#405a49]">帳號生命週期</CardTitle><CardDescription className="mt-1">停用帳號後將無法再存取受保護資料，歷史紀錄仍會保留。</CardDescription></div></div></CardHeader><CardContent>{users.data?.length ? <div className="divide-y divide-[#eee9e1]">{users.data.map(person => <div key={person.id} className="flex flex-col gap-3 py-3 first:pt-0 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium text-[#52645a]">{person.name || "未命名使用者"}</p><p className="mt-0.5 text-xs text-[#99a099]">{person.email || "尚未提供電子郵件"} · {person.role}</p></div><Button size="sm" variant={person.isActive ? "outline" : "default"} disabled={setStatus.isPending || person.id === user?.id} onClick={() => { const next = !person.isActive; if (window.confirm(next ? `確定要啟用「${person.name || person.email || "此使用者"}」嗎？` : `確定要停用「${person.name || person.email || "此使用者"}」嗎？此帳號將立即無法使用系統。`)) setStatus.mutate({ userId: person.id, isActive: next }); }} className={person.isActive ? "rounded-lg border-[#e2d7cc] text-[#8c6250]" : "rounded-lg bg-[#355f4d] hover:bg-[#294a3d]"}>{person.isActive ? <><UserX className="mr-1.5 h-3.5 w-3.5" />停用</> : <><UserCheck className="mr-1.5 h-3.5 w-3.5" />啟用</>}</Button></div>)}</div> : <EmptyState icon={UserCheck} title="尚無可管理使用者" detail="使用者首次登入後會顯示於此處。" />}</CardContent></Card>
      <Card className="border-[#e3dbcf] bg-[#fdfcf9] shadow-none"><CardHeader><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#edf2f5] text-[#4f7587]"><History className="h-5 w-5" /></div><div><CardTitle className="font-serif text-xl text-[#405a49]">最近操作稽核</CardTitle><CardDescription className="mt-1">僅呈現變更摘要，不收錄關懷與代禱的完整內容。</CardDescription></div></div></CardHeader><CardContent>{auditLogs.data?.length ? <div className="max-h-105 divide-y divide-[#eee9e1] overflow-y-auto">{auditLogs.data.map(log => <div key={log.id} className="py-3 first:pt-0"><div className="flex items-start justify-between gap-3"><div><p className="font-medium text-[#52645a]">{log.summary}</p><p className="mt-1 text-xs text-[#9a938a]">{log.actorName || log.actorEmail || "系統使用者"} · {dateText(log.createdAt)}</p></div><Badge variant="outline" className="shrink-0 border-[#d4e2d1] bg-[#eff5ed] text-[#50755a]">{log.action}</Badge></div></div>)}</div> : <EmptyState icon={History} title="尚無稽核紀錄" detail="資料異動、角色調整、帳號啟停與匯出後，將在此處留下摘要。" />}</CardContent></Card></div></div>;
}

function PermissionPanel() {
  const { user } = useAuth(); const users = trpc.users.list.useQuery(undefined, { enabled: user?.role === "Admin", retry: false }); const update = trpc.users.updateRole.useMutation({ onSuccess: () => { users.refetch(); toast.success("角色權限已更新"); } });
  if (user?.role !== "Admin") return <EmptyState icon={Check} title="您沒有此頁面的存取權" detail="角色權限管理僅限 Admin 使用。" />;
  return <div className="space-y-6"><Card className="border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardHeader><CardTitle className="font-serif text-xl text-[#405a49]">角色說明</CardTitle><CardDescription>權限檢查會同時在後端程序與前端導覽套用，敏感支持資訊僅供 Admin 查閱。</CardDescription></CardHeader><CardContent className="grid gap-3 md:grid-cols-3"><RoleCard title="Admin" text="管理全站資料、支持資訊、活動公告與角色設定。" tone="bg-[#edf4eb]" /><RoleCard title="Leader" text="管理受指派小組的名冊、出席與關懷記錄。" tone="bg-[#f9f2e7]" /><RoleCard title="Member" text="查看已啟用宣教士、代禱事項、活動與公告。" tone="bg-[#edf2f5]" /></CardContent></Card><Card className="border-[#e8e2d8] bg-[#fdfcf9] shadow-none"><CardHeader><CardTitle className="font-serif text-xl text-[#405a49]">使用者角色</CardTitle></CardHeader><CardContent>{users.data?.length ? <div className="divide-y divide-[#eee9e1]">{users.data.map(person => <div key={person.id} className="flex flex-col gap-3 py-3 first:pt-0 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium text-[#52645a]">{person.name || "未命名使用者"}</p><p className="text-xs text-[#99a099]">{person.email || "尚未提供電子郵件"}</p></div><Select value={person.role} onValueChange={role => update.mutate({ userId: person.id, role: role as "Admin" | "Leader" | "Member" })}><SelectTrigger className="w-36"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="Admin">Admin</SelectItem><SelectItem value="Leader">Leader</SelectItem><SelectItem value="Member">Member</SelectItem></SelectContent></Select></div>)}</div> : <EmptyState icon={UsersRound} title="尚無可管理使用者" detail="使用者首次登入後會顯示於此處。" />}</CardContent></Card></div>;
}

function Field({ label, name, defaultValue, type = "text", required = false }: { label: string; name: string; defaultValue?: string | null; type?: string; required?: boolean }) { return <div><Label htmlFor={name}>{label}</Label><Input id={name} name={name} type={type} defaultValue={defaultValue ?? ""} required={required} className="mt-2" /></div>; }
function GroupChecks({ groups }: { groups: any[] }) { return <div><Label>指定對象小組（選填）</Label>{groups.length ? <div className="mt-2 grid gap-2 rounded-xl border border-[#e7e0d7] p-3 sm:grid-cols-2">{groups.map(group => <label key={group.id} className="flex items-center gap-2 text-sm text-[#596a60]"><Checkbox name="groupIds" value={String(group.id)} />{group.name}</label>)}</div> : <p className="mt-2 text-xs text-[#9b958d]">尚無可選小組；不選擇代表對全體公開。</p>}</div>; }
function StatusBadge({ status }: { status: string }) { return <Badge variant="outline" className={status === "active" ? "border-[#d1e3cf] bg-[#eff6ed] text-[#50775a]" : "border-[#e2d7cc] bg-[#f6f2ed] text-[#8c8074]"}>{status === "active" ? "啟用" : "停用"}</Badge>; }
function PrayerBadge({ status }: { status: string }) { return <Badge className={status === "praying" ? "bg-[#f1dfbf] text-[#8c5b23] hover:bg-[#f1dfbf]" : "bg-[#dcebdc] text-[#477254] hover:bg-[#dcebdc]"}>{status === "praying" ? "代禱中" : "已回應"}</Badge>; }
function Info({ label, value }: { label: string; value: string }) { return <div className="rounded-xl bg-[#f7f4ee] p-3"><p className="text-[10px] font-bold tracking-wider text-[#a19281]">{label}</p><p className="mt-1 truncate text-sm text-[#58675e]">{value}</p></div>; }
function RoleCard({ title, text, tone }: { title: string; text: string; tone: string }) { return <div className={`rounded-2xl p-4 ${tone}`}><p className="font-serif text-xl font-semibold text-[#405a49]">{title}</p><p className="mt-2 text-sm leading-6 text-[#68756c]">{text}</p></div>; }
function frequencyLabel(value: string) { return ({ monthly: "每月", quarterly: "每季", yearly: "每年", one_time: "一次性" } as Record<string, string>)[value] ?? value; }
function careMethodLabel(value: string) { return ({ phone: "電話", visit: "探訪", message: "訊息", meeting: "面談", other: "其他" } as Record<string, string>)[value] ?? value; }
function followLabel(value: string) { return ({ none: "暫無跟進", pending: "待跟進", completed: "已完成" } as Record<string, string>)[value] ?? value; }
